questionvariables.text:
px : rand([-1,1]);
py : rand([-1,1]);
fx : rand([-1,1]);
fy : rand([-1,1]);
bs : rand([-2,2]);
br : rand([-1,1]);
/* fish geometry - MUST match the JSXGraph fish (fs, ex, ey) */
fs : 0.6;
ex : 0.8;
ey : 0.16;
qx : px + fs*ex;
qy : py + fs*ey;
/* colour of the hidden target fish: perfect colouring by mirror-crossing parity */
hx0 : mod(mod(bs,2) + (if fx = -1 then 1 else 0), 2);
hy0 : mod(mod(br,2) + (if fy = -1 then 1 else 0), 2);
ci : 2*hx0 + hy0;
correctval : ci + 1;
cnames : ["red","orange","teal","green"];
colourword : cnames[correctval];
ta : makelist([j, is(j = correctval), cnames[j]], j, 1, 4);
/* target is (|bs|+|br|) boxes out; reflect stops one short */
targetlevel : abs(bs) + abs(br);
maxlevel : targetlevel - 1;
